"""REST v2 handler for the auto-generated file domain."""

from __future__ import annotations

from http import HTTPStatus
from typing import TYPE_CHECKING

from ai.backend.common.api_handlers import APIResponse, BodyParam, PathParam
from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AutoGeneratedFileScopeInput,
    CreateAutoGeneratedFileInput,
    MySearchAutoGeneratedFilesInput,
    PurgeAutoGeneratedFileInput,
    ScopedSearchAutoGeneratedFilesInput,
    SwitchDefaultAutoGeneratedFileInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import AutoGeneratedFileScope
from ai.backend.common.dto.manager.v2.rbac.types import UUIDScope
from ai.backend.manager.api.rest.v2.path_params import AutoGeneratedFileIdPathParam
from ai.backend.manager.dto.context import UserContext

if TYPE_CHECKING:
    from ai.backend.manager.api.adapters.auto_generated_file.adapter import (
        AutoGeneratedFileAdapter,
    )


class V2AutoGeneratedFileHandler:
    """REST v2 handler for adding, removing, reading and switching the default of
    auto-generated files."""

    _adapter: AutoGeneratedFileAdapter

    def __init__(self, *, adapter: AutoGeneratedFileAdapter) -> None:
        self._adapter = adapter

    async def create(self, body: BodyParam[CreateAutoGeneratedFileInput]) -> APIResponse:
        """Add a file that is not the default of its path."""
        result = await self._adapter.create(body.parsed)
        return APIResponse.build(status_code=HTTPStatus.CREATED, response_model=result)

    async def scoped_search(
        self, body: BodyParam[ScopedSearchAutoGeneratedFilesInput]
    ) -> APIResponse:
        """Search the files of the named domains, projects and users, combined with OR."""
        result = await self._adapter.scoped_search(body.parsed)
        return APIResponse.build(status_code=HTTPStatus.OK, response_model=result)

    async def my_search(
        self, user_ctx: UserContext, body: BodyParam[MySearchAutoGeneratedFilesInput]
    ) -> APIResponse:
        """Search the current user's own files."""
        result = await self._adapter.scoped_search(
            ScopedSearchAutoGeneratedFilesInput(
                scope=AutoGeneratedFileScope(user=[UUIDScope(value=user_ctx.user_uuid)]),
                filter=body.parsed.filter,
                order=body.parsed.order,
                first=body.parsed.first,
                after=body.parsed.after,
                last=body.parsed.last,
                before=body.parsed.before,
                limit=body.parsed.limit,
                offset=body.parsed.offset,
            )
        )
        return APIResponse.build(status_code=HTTPStatus.OK, response_model=result)

    async def switch_default(
        self,
        path: PathParam[AutoGeneratedFileIdPathParam],
        body: BodyParam[AutoGeneratedFileScopeInput],
    ) -> APIResponse:
        """Make a file the default of its path."""
        result = await self._adapter.switch_default(
            SwitchDefaultAutoGeneratedFileInput(
                scope=body.parsed, id=AutoGeneratedFileID(path.parsed.auto_generated_file_id)
            )
        )
        return APIResponse.build(status_code=HTTPStatus.OK, response_model=result)

    async def purge(self, path: PathParam[AutoGeneratedFileIdPathParam]) -> APIResponse:
        """Remove a file that is not the default of its path."""
        result = await self._adapter.purge(
            PurgeAutoGeneratedFileInput(id=AutoGeneratedFileID(path.parsed.auto_generated_file_id))
        )
        return APIResponse.build(status_code=HTTPStatus.OK, response_model=result)
